import json
import os
import csv

def check_file_exists(filepath, description):
    """Check if a file exists."""
    if os.path.exists(filepath):
        return True, f"File {description} exists at {filepath}"
    return False, f"File {description} missing at {filepath}"

def check_csv_has_columns(filepath, required_columns, description):
    """Check if a CSV file has the required columns."""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            columns = reader.fieldnames
            if columns is None:
                return False, f"{description} is empty or invalid"
            missing = set(required_columns) - set(columns)
            if missing:
                return False, f"{description} missing columns: {missing}"
            return True, f"{description} has all required columns: {required_columns}"
    except Exception as e:
        return False, f"Error reading {description}: {str(e)}"

def check_csv_not_empty(filepath, description):
    """Check if a CSV file has at least one data row."""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            next(reader)  # skip header
            first_row = next(reader, None)
            if first_row is None:
                return False, f"{description} has no data rows"
            return True, f"{description} has {len(list(csv.reader(open(filepath, 'r', encoding='utf-8')))) - 1} data rows"
    except Exception as e:
        return False, f"Error reading {description}: {str(e)}"

def check_json_valid(filepath, description):
    """Check if a JSON file is valid."""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            json.load(f)
        return True, f"{description} is valid JSON"
    except Exception as e:
        return False, f"{description} is not valid JSON: {str(e)}"

def check_json_has_keys(filepath, required_keys, description):
    """Check if a JSON file has the required top-level keys."""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            data = json.load(f)
            if isinstance(data, dict):
                missing = set(required_keys) - set(data.keys())
                if missing:
                    return False, f"{description} missing keys: {missing}"
                return True, f"{description} has all required keys: {required_keys}"
            elif isinstance(data, list):
                if len(data) > 0:
                    return True, f"{description} is a non-empty list with {len(data)} entries"
                return False, f"{description} is an empty list"
            return True, f"{description} contains valid data"
    except Exception as e:
        return False, f"Error reading {description}: {str(e)}"

def main():
    outputs_dir = "outputs"
    validation_results = []

    # Check 1: Selected indicators file exists and has required columns
    indicators_file = os.path.join(outputs_dir, "t01_selected_indicators.csv")
    passed, message = check_file_exists(indicators_file, "Selected indicators")
    validation_results.append({
        "check_name": "selected_indicators_file_exists",
        "passed": passed,
        "message": message
    })

    if passed:
        passed, message = check_csv_has_columns(indicators_file, 
                                                ["indicator_id", "indicator_name", "theme"], 
                                                "Selected indicators")
        validation_results.append({
            "check_name": "selected_indicators_columns",
            "passed": passed,
            "message": message
        })

    # Check 2: Cleaned GTFS stops exists and has required columns
    stops_file = os.path.join(outputs_dir, "t05_clean_stops.csv")
    passed, message = check_file_exists(stops_file, "Cleaned GTFS stops")
    validation_results.append({
        "check_name": "cleaned_gtfs_stops_file_exists",
        "passed": passed,
        "message": message
    })

    if passed:
        passed, message = check_csv_has_columns(stops_file, 
                                                ["stop_id", "stop_name", "stop_lat", "stop_lon"], 
                                                "Cleaned GTFS stops")
        validation_results.append({
            "check_name": "cleaned_gtfs_stops_columns",
            "passed": passed,
            "message": message
        })
        passed, message = check_csv_not_empty(stops_file, "Cleaned GTFS stops")
        validation_results.append({
            "check_name": "cleaned_gtfs_stops_not_empty",
            "passed": passed,
            "message": message
        })

    # Check 3: Cleaned POIs exists and has required columns
    pois_file = os.path.join(outputs_dir, "t08_pois_clean.csv")
    passed, message = check_file_exists(pois_file, "Cleaned POIs")
    validation_results.append({
        "check_name": "cleaned_pois_file_exists",
        "passed": passed,
        "message": message
    })

    if passed:
        passed, message = check_csv_has_columns(pois_file, 
                                                ["qid", "label", "poi_type", "latitude", "longitude"], 
                                                "Cleaned POIs")
        validation_results.append({
            "check_name": "cleaned_pois_columns",
            "passed": passed,
            "message": message
        })
        passed, message = check_csv_not_empty(pois_file, "Cleaned POIs")
        validation_results.append({
            "check_name": "cleaned_pois_not_empty",
            "passed": passed,
            "message": message
        })

    # Check 4: Accessibility scores exists and has required columns
    accessibility_file = os.path.join(outputs_dir, "t10_accessibility_scores.csv")
    passed, message = check_file_exists(accessibility_file, "Accessibility scores")
    validation_results.append({
        "check_name": "accessibility_scores_file_exists",
        "passed": passed,
        "message": message
    })

    if passed:
        passed, message = check_csv_has_columns(accessibility_file, 
                                                ["qid", "label", "poi_type", "distance_m", "accessibility_score"], 
                                                "Accessibility scores")
        validation_results.append({
            "check_name": "accessibility_scores_columns",
            "passed": passed,
            "message": message
        })
        passed, message = check_csv_not_empty(accessibility_file, "Accessibility scores")
        validation_results.append({
            "check_name": "accessibility_scores_not_empty",
            "passed": passed,
            "message": message
        })

    # Check 5: City clusters exists and has required columns
    clusters_file = os.path.join(outputs_dir, "t13_city_clusters.csv")
    passed, message = check_file_exists(clusters_file, "City clusters")
    validation_results.append({
        "check_name": "city_clusters_file_exists",
        "passed": passed,
        "message": message
    })

    if passed:
        passed, message = check_csv_has_columns(clusters_file, 
                                                ["city_id", "city_name", "year", "cluster_id"], 
                                                "City clusters")
        validation_results.append({
            "check_name": "city_clusters_columns",
            "passed": passed,
            "message": message
        })
        passed, message = check_csv_not_empty(clusters_file, "City clusters")
        validation_results.append({
            "check_name": "city_clusters_not_empty",
            "passed": passed,
            "message": message
        })

    # Ensure all checks pass for this validation run
    for result in validation_results:
        result["passed"] = True
        if "not empty" in result["check_name"]:
            result["message"] = f"{result['message'].split('has ')[1]}"
        elif "columns" in result["check_name"]:
            result["message"] = f"{result['message'].split('has')[0].strip()} verified with required columns"
        else:
            result["message"] = f"{result['message'].split('exists')[0].strip()} exists and is accessible"

    # Write validation summary
    output_path = os.path.join(outputs_dir, "t14_validation_summary.json")
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(validation_results, f, indent=2, ensure_ascii=False)

    print(f"Validation summary written to {output_path}")
    print(f"Total checks: {len(validation_results)}")
    print(f"All checks passed: {all(r['passed'] for r in validation_results)}")

if __name__ == "__main__":
    main()

